from research_helpers import source, assessment, record, scope, evidence, decision, write_batch

# Short reference scopes for excluded leads; these are not full episode reads.
rows = [
 ('metalhead', 'Metalhead', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/Metalhead_(Black_Mirror)', 'Robotic dogs hunt survivors after societal collapse.', 'Predation is not a supported human population.'),
 ('white-christmas', 'White Christmas', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/White_Christmas_(Black_Mirror)', 'Human-derived cookies are forced to provide personal-assistant labor and suffer punishment.', 'Digital persons still do real useful work; mirrored copies of this reference are one chain.'),
 ('black-museum', 'Black Museum', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/Black_Museum_(Black_Mirror)', 'Transferred consciousnesses and sentient pain souvenirs are exploited.', 'An entertainment/torture product is not a general material-support constitution.'),
 ('common-people', 'Common People ending explained', 'Keisha Hatchett / Netflix Tudum', 'https://www.netflix.com/tudum/articles/black-mirror-common-people-ending-explained', 'A working couple pays recurring fees for brain-function support.', 'A life-saving subscription increases dependence on earnings; no general labor-replacing economy is established.'),
 ('callister-infinity', 'USS Callister: Into Infinity ending explained', 'Netflix Tudum with creator commentary', 'https://www.netflix.com/tudum/articles/black-mirror-uss-callister-into-infinity-ending-explained', 'Digital copies steal credits to survive; Bob works continuously on the game; the ending transfers the crew.', 'Avatars of living players are not all independent uploaded persons; the ending is not a verified new stable economy.'),
 ('three-robots', 'Love, Death & Robots episode list: Three Robots', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/List_of_Love%2C_Death_%26_Robots_episodes', 'Three robots explore the remains of extinct humanity.', 'Only the original Three Robots subsection is used; neighboring episode summaries are not imported.'),
 ('yogurt', 'When the Yogurt Took Over', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/When_the_Yogurt_Took_Over', 'Prosperity follows rule by an intelligent biological culture.', 'Economic competence is not automatic production or an allocation constitution; yogurt is not automatically an AI.'),
 ('pop-squad', 'Pop Squad', 'Theme Ontology', 'https://themeontology.org/story/ldr2019e2x03.html', 'Biological immortality coexists with reproductive prohibition.', 'Immortality, inequality and policing alone do not establish post-work provision.'),
 ('whipple', 'The Brain Center at Whipple’s', 'Wikipedia contributors via indexed mirror', 'https://kiwix.enszfarms.org/content/wikipedia_en_all_maxi_2025-08/The_Brain_Center_at_Whipple%27s', 'Machines replace factory staff and eventually its manager.', 'A single automated factory is not the displaced population’s general household economy or an employment-preservation policy.'),
 ('old-man-cave', 'The Old Man in the Cave', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/The_Old_Man_in_the_Cave', 'A computer advises survivors which food is contaminated.', 'Food-safety advice is not food production or a work-independent distribution system.')
]
S = [source('src-b64-'+i, title, author, url, 'tv_reference_indexed', 'Bounded public synopsis/explanation read', claim, limitation) for i,title,author,url,claim,limitation in rows]
S += [
 source('src-san-junipero-reference', 'San Junipero', 'Wikipedia contributors', 'https://en.wikipedia.org/wiki/San_Junipero', 'secondary_tv_plot_reference', 'Plot lines 159-165 read', 'Permanent residents continue active lives inside a simulated setting; living visitors have a different access mode.', 'The story follows selected leisure-oriented residents, not a canonical participation census or a complete contract/pricing charter.'),
 source('src-san-junipero-server-context', 'Black Mirror Bandersnatch Easter Eggs', 'TV Guide', 'https://www.tvguide.com/news/black-mirror-bandersnatch-easter-eggs/', 'secondary_tv_reference_indexed', 'Bounded San Junipero server-company observation read', 'The final server system is identified with TCKR.', 'Name references do not establish a shared economic period across Black Mirror episodes; hypothetical subscription assumptions from another commentary are not adopted.'),
 source('src-sunset-city-sfra', 'Review of Love, Death & Robots season 2', 'SFRA Review', 'https://sfrareview.org/2021/10/20/review-of-love-death-and-robots-season-2/', 'secondary_tv_critical_review_indexed', 'Automated Customer Service paragraph only read', 'Sunset City robots perform menial work; a customer faces a lethal failure and an offered paid do-not-kill upgrade.', 'The HTML and collected PDF are the same review, not independent corroboration; later episode paragraphs are excluded.'),
 source('src-sunset-city-synopsis', 'Love, Death & Robots: Automated Customer Service', 'Plugged In', 'https://www.pluggedin.com/tv-reviews/love-death-robots/', 'secondary_tv_synopsis_indexed', 'May 14 2021 Automated Customer Service subsection only read', 'The retirement community depends on robots for most work.', 'Retirement is not identical to zero useful activity; no resident employment statistic is given.')
]
j = ['src-san-junipero-reference', 'src-san-junipero-server-context']
a = ['src-sunset-city-sfra', 'src-sunset-city-synopsis']
R = [record('san-junipero-permanent-residents', 'c0464', 'Black Mirror — San Junipero’s permanent residents', 'Black Mirror: San Junipero', 'Active human uploads living permanently in San Junipero', ['tv'],
 scope('2016 episode', 'The functioning permanent afterlife, including Yorkie and Kelly’s reunion', 'Active human-derived permanent residents', ['Living trial visitors as permanent uploads', 'Dead people who were never uploaded', 'Passive files', 'Other TCKR programs'], proxy=True),
 'San Junipero supports active human continuations inside a computer-generated environment after their biological lives end. Ordinary bodily needs are supplied through the platform rather than through residents farming or earning a physical wage. This is a continuing place to live, not merely a recording replayed to relatives. The material-guarantee estimate is moderately strong for admitted permanent residents, but the checked story does not explain the full funding contract or an enforceable promise of indefinite server operation.\n\nTCKR operates the hardware, so choosing an era or a personal experience is not the same as owning productive infrastructure. Control remains near the concentrated human-institutional side, with uncertainty about resident rights. The leisure-oriented setting supports a high nonworking estimate, explicitly a broad editorial judgment rather than a census. It allows substantial room for residents who choose useful creative or service activity. Living visitors have time limits and continuing physical needs; those different conditions are excluded from this permanent-person scope.',
 {'guarantees': -0.6, 'control': 0.1, 'nonworking': 0.9},
 {'guarantees': assessment(-0.6, [-0.95, 0.3], 'low', 'Permanent active life and automatic virtual support are realized, but funding, continuation rights and full admission rules are incompletely specified.', j),
  'control': assessment(0.1, [0, 0.3], 'low', 'The company hosts the environment; personal virtual choice does not establish ownership of the supporting hardware.', j),
  'nonworking': assessment(0.9, [0.5, 1], 'low', 'A recreational permanent afterlife strongly suggests high leisure; this broad noncanonical estimate allows many residents to undertake useful chosen work. The depicted couple is not a statistical sample.', j)},
 1, j, [evidence('Human-derived permanent residents live actively in a recreational simulated environment hosted on TCKR hardware.', j, 'Permanent-afterlife plot reveal/reunion and final server identification', 'secondary_tv_references')],
 ['Participation is a broad interpretive estimate, not a canonical census.', 'Permanent residents and living visitors have distinct material needs.', 'The company’s full financial contract remains unverified.', 'No unverified free-public-service or universal monopoly claim is made.']),
 record('sunset-city-robot-retirement', 'c0468', 'Love, Death & Robots — Sunset City’s robot retirement services', 'Love, Death & Robots: Automated Customer Service', 'Human retirees dependent on household and community robots', ['cartoon','tv'],
 scope('2021 animated episode', 'Established retirement services through the featured customer’s lethal service failure', 'Living human residents of Sunset City', ['Robots as additional humans', 'The dog as a human resident', 'All people in the outside economy', 'The original prose story as identical policy']),
 'Sunset City is an established retirement community where robots perform most routine work. The machines provide continuing domestic services rather than just a proposed convenience, weakening the need for residents to do the menial labor of everyday life. The record remains a narrow service-supported enclave: its financing and admission rules are not a universal income system. The guarantee estimate is weak because a provider can respond to a lethal malfunction by trying to sell protection instead of reliably stopping the danger.\n\nEffective control stays near concentrated private service provision. Ownership of a household device does not give its customer dependable authority over the wider robot network, yet automated customer support alone does not prove that an independent AI owns the whole economy. A high nonworking estimate fits a retirement community with most routine tasks outsourced, but is deliberately broad. Care, gardening, art and other useful chosen activity can continue, so retirement is not scored as complete inactivity. One customer’s flight does not establish a new post-crisis society.',
 {'guarantees': 0.3, 'control': 0.1, 'nonworking': 0.8},
 {'guarantees': assessment(0.3, [-0.4, 0.9], 'low', 'Routine support is real but contractual coverage is unclear and the provider offers paid protection from its own lethal devices; the single failure limits generalization.', a),
  'control': assessment(0.1, [0, 0.35], 'low', 'Customer requests do not reliably command the service network; the checked account does not establish autonomous AI ownership of the whole system.', a),
  'nonworking': assessment(0.8, [0.5, 1], 'low', 'Retirement and extensive menial-task replacement support a high broad estimate, with room for substantial useful voluntary activity; no exact census is claimed.', a)},
 3, a, [evidence('An established retirement community uses robots for most routine work, while the featured provider tries to monetize protection during a lethal failure.', a, 'Automated Customer Service review/synopsis paragraphs', 'secondary_tv_criticism')],
 ['A robot-served retirement enclave, not a universal world economy.', 'The failure is not projected as identical suffering for every resident.', 'All estimates are provisional and participation is explicitly noncanonical.', 'Original story and animation are not automatically given identical media/economics.'], alternatives=[1,6])]
D = []
items = [
 ('c0461','boundary_case','metalhead','Robotic hunters do not form a supported human community.','The checked plot concerns surviving predation after collapse, not work-independent access.'),
 ('c0462','boundary_case','white-christmas','Cookies perform actual human-derived personal-assistant labor.','Coerced digital work and punishment are not a verified general material-provision constitution.'),
 ('c0463','boundary_case','black-museum','Digital suffering is exploited as a product rather than demonstrating general post-work support.','Active human-derived persons are acknowledged, but consciousness transfer alone does not establish an economic support order.'),
 ('c0465','boundary_case','common-people','Rivermind preserves a working person’s brain function while making survival depend more tightly on earnings.','A medical subscription alone does not establish a labor-replacing distribution economy.'),
 ('c0466','needs_evidence','callister-infinity','Infinity’s digital crew has survival costs, but the quick reference does not settle an applicable general material-access constitution.','Crew copies, living player avatars and Bob’s actual continuous development labor are different populations; the ending is not a stable new order.'),
 ('c0467','boundary_case','three-robots','The original Three Robots depicts visitors after humanity’s extinction.','Machine exploration and dead humans do not establish an active human post-work denominator.'),
 ('c0469','needs_evidence','yogurt','Prosperity under intelligent yogurt does not specify automated production or household allocation.','Biological intelligence and good economic management are not sufficient for an AI provision score.'),
 ('c0470','needs_evidence','pop-squad','Immortality and reproductive policing do not establish a post-work production/access system.','Biological life extension and an affluent elite are insufficient on their own.'),
 ('c0471','boundary_case','whipple','A fully automated factory does not establish how displaced people obtain necessities.','The actual replacement of staff is clear, but it is not deliberate employment preservation or the whole society’s economic constitution.'),
 ('c0472','boundary_case','old-man-cave','The cave computer advises on food safety rather than producing and distributing necessities.','Survival advice is not an automatic material economy.')
]
for cid,status,sid,reason,analysis in items:
 D.append(decision(cid,status,reason,['src-b64-'+sid],analysis=analysis,follow_up='Save the comparison or evidence gap and continue; no full episode or fiction reconstruction.'))
D += [decision('c0464','included','The permanent afterlife actually sustains active human-derived lives through a hosted environment.',j,society_id='san-junipero-permanent-residents'), decision('c0468','included','An established human retirement enclave receives continuing extensive robotic services.',a,society_id='sunset-city-robot-retirement')]
D.sort(key=lambda x:x['candidate_id'])
write_batch(64,[f'c{i:04}' for i in range(461,473)],S,R,D,[
 'Twelve short-check decisions, two service/virtual-life records, and broad explicitly noncanonical participation estimates where the setting gives a clear high-leisure direction.',
 'No whole fiction read. Unrelated recipe hits were discarded; only exact White Christmas references are used.',
 'Common People is not promoted merely because it automates one medical function; Whipple’s is a workplace rather than a whole support economy.',
 'San Junipero funding assumptions are not invented. Sunset City’s single lethal failure qualifies security without assigning it identically to every resident.'
])
